import React from 'react'
import { HeadFC, PageProps } from 'gatsby'
import { AuthProvider } from '../../../contexts/AuthContext'
import { LanguageProvider } from '../../../i18n/LanguageContext'
import { Toaster } from 'react-hot-toast'
import VenueDetail from '../../../components/venue/VenueDetail'
import { getVenueById } from '../../../data/venues'

const VenuePage: React.FC<PageProps> = ({ params }) => {
  const venueId = params?.venueId as string
  
  return (
    <LanguageProvider>
      <AuthProvider>
        <VenueDetail venueId={venueId} />
        <Toaster 
          position="top-right"
          toastOptions={{
            duration: 3000,
            style: {
              background: '#363636',
              color: '#fff',
            },
          }}
        />
      </AuthProvider>
    </LanguageProvider>
  )
}

export const Head: HeadFC<any, { venueId: string }> = ({ params }) => {
  const venueId = params?.venueId as string
  const venue = getVenueById(venueId)
  
  // クライアントサイドで言語を判定
  const getMetaContent = () => {
    if (typeof window === 'undefined') {
      // サーバーサイド/ビルド時はデフォルト（日本語）
      return {
        title: venue ? `${venue.name} - 美辞学ナビ` : '美辞学ナビ',
        description: venue 
          ? `${venue.name}（${venue.location.prefecture}）の参加表明者をチェック！`
          : 'Reol美辞学ツアーの会場詳細'
      }
    }
    
    // クライアントサイドで言語を取得
    const language = localStorage.getItem('reol-language') || 'ja'
    
    if (language === 'en') {
      return {
        title: venue ? `${venue.name} - Bijigaku Navi` : 'Bijigaku Navi',
        description: venue 
          ? `Check attendees for ${venue.name} (${venue.location.prefecture})!`
          : 'Reol Bijigaku Tour venue details'
      }
    }
    
    return {
      title: venue ? `${venue.name} - 美辞学ナビ` : '美辞学ナビ',
      description: venue 
        ? `${venue.name}（${venue.location.prefecture}）の参加表明者をチェック！`
        : 'Reol美辞学ツアーの会場詳細'
    }
  }

  const meta = getMetaContent()

  return (
    <>
      <title>{meta.title}</title>
      <meta name="description" content={meta.description} />
      <meta property="og:title" content={meta.title} />
      <meta property="og:description" content={meta.description} />
      <meta property="og:type" content="website" />
    </>
  )
}

export default VenuePage